// 1. Seeding Source (Non-deterministic, usually)
std::random_device rd;

// 2. Engine (The stateful generator)
std::mt19937 engine(rd());

// Alternative: Use the default_random_engine if system allows optimization
// std::default_random_engine engine(rd());

// 3. Uniform Integer Distribution (Range [1, 6])
std::uniform_int_distribution<int> dice(1, 6);
int roll = dice(engine);

// 4. Uniform Real Distribution (Range [0.0, 1.0))
std::uniform_real_distribution<> unit_range(0.0, 1.0);
double probability = unit_range(engine);

// 5. Normal (Gaussian) Distribution (Mean=10.0, StdDev=2.0)
std::normal_distribution<> normal_dist(10.0, 2.0);
double sample = normal_dist(engine);

// 6. Non-Uniform Example (Poisson)
std::poisson_distribution<> poisson(5.0);
int count = poisson(engine);
